def checked_file(path, digest, max_bytes, uid=None, mode=None):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        info=os.fstat(fd)
        if not (stat.S_ISREG(info.st_mode) and info.st_nlink==1 and info.st_size<=max_bytes
                and (uid is None or info.st_uid==uid)
                and (mode is None or stat.S_IMODE(info.st_mode)==mode)):
            raise RuntimeError('file identity mismatch: '+str(path))
        with os.fdopen(fd,'rb') as stream:
            fd=-1; data=stream.read(max_bytes+1)
    finally:
        if fd>=0:os.close(fd)
    if len(data)>max_bytes or hashlib.sha256(data).hexdigest()!=digest:
        raise RuntimeError('file digest mismatch: '+str(path))
    return data

