def client_input(sql, timeout=120):
    ctl.verify(rid,'target',live_identity.SENTINEL,state['uuids']['target'])
    socket=ctl.paths(rid,'target')[2]
    args=['/usr/bin/mysql','--no-defaults','--protocol=SOCKET','--socket='+str(socket),
          '--user=root','--batch','--raw','--skip-column-names']
    cp=subprocess.run(args,input=sql,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,
                      timeout=timeout,env=ctl.ENV,check=False)
    if cp.returncode:raise RuntimeError('isolated mysql command failed')
    return cp.stdout

